mapper.select:
SELECT COUNT(*)
FROM MEMBER
WHERE MEMBER_EMAIL = #{memberEmail}

mapper.update:
UPDATE MEMBER
SET
    MEMBER_NAME = #{memberName}
    , MEMBER_BIRTH = #{memberBirth}
    , MEMBER_PHONE = #{memberPhone}
    , MEMBER_ADDR = #{memberAddr}
    , MEMBER_ADDR_DETAIL = #{memberAddrDetail}
WHERE MEMBER_EMAIL = #{memberEmail}

UPDATE MEMBER
SET
    MEMBER_PASSWORD = #{memberPw}
WHERE MEMBER_EMAIL = #{memberEmail}

UPDATE MEMBER
SET
    REFRESH_TOKEN = #{refreshToken},
    REFRESH_TOKEN_EXPIRY = #{refreshTokenExpiry}
WHERE MEMBER_EMAIL = #{memberEmail}

mapper.select:
SELECT MEMBER_ID, MEMBER_ROLE, MEMBER_EMAIL, MEMBER_NAME, REFRESH_TOKEN, REFRESH_TOKEN_EXPIRY
FROM MEMBER
WHERE REFRESH_TOKEN = #{refreshToken}

SELECT MEMBER_ID
FROM MEMBER
WHERE MEMBER_EMAIL = #{memberEmail}

SELECT MEMBER_EMAIL
FROM MEMBER
WHERE MEMBER_NAME = #{name}
  AND MEMBER_PHONE = #{phone}
LIMIT 1

SELECT COUNT(*)
FROM MEMBER
WHERE MEMBER_EMAIL = #{email}
  AND MEMBER_NAME = #{name}
  AND MEMBER_PHONE = #{phone}

SELECT MEMBER_NAME
FROM MEMBER
WHERE MEMBER_EMAIL = #{email}

mapper.update:
UPDATE MEMBER
SET FCM_TOKEN = #{fcmToken}
WHERE MEMBER_ID = #{memberId}

mapper.select:
SELECT FCM_TOKEN
FROM MEMBER
WHERE MEMBER_ID = #{memberId}
